const { spot, strike, rate, vol, time } = args;
const erf = (x) => {
  const sign = x >= 0 ? 1 : -1;
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741, a4 = -1.453152027, a5 = 1.061405429, p = 0.3275911;
  const absX = Math.abs(x);
  const t = 1.0 / (1.0 + p * absX);
  const y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-absX * absX);
  return sign * y;
};
const normCDF = (x) => 0.5 * (1.0 + erf(x / Math.SQRT2));
const sqrtT = Math.sqrt(time);
const d1 = (Math.log(spot / strike) + (rate + 0.5 * vol * vol) * time) / (vol * sqrtT);
const d2 = d1 - vol * sqrtT;
const nd1 = normCDF(d1);
const nd2 = normCDF(d2);
const callPrice = spot * nd1 - strike * Math.exp(-rate * time) * nd2;
const delta = nd1;
return { callPrice, delta, d1, d2 };

